"""Verify PDF fixtures generated by browser.cjs (requires pypdf and pdfplumber)."""
import json
from pathlib import Path
import re
import pdfplumber
from pypdf import PdfReader

ROOT = Path(__file__).resolve().parents[1] / "tmp" / "qa"
expected = json.loads((ROOT / "sample-expected.json").read_text(encoding="utf-8"))


def compact(text):
    return re.sub(r"\s+", "", text)


def body(reader):
    return "\n".join(re.sub(r"Application Register .*?UAT results\n\d+ / \d+\s*$", "", page.extract_text()) for page in reader.pages)


all_pdf = PdfReader(ROOT / "all-scenarios.pdf")
all_text = compact(body(all_pdf))
fields = ["caseKey", "scenarioId", "title", "goal", "preconditions", "steps", "expected"]
for scenario in expected["source"]["scenarios"]:
    for field in fields:
        assert compact(scenario[field]) in all_text, (scenario["id"], field)
positions = [all_text.index(compact(s["caseKey"])) for s in expected["source"]["scenarios"]]
assert positions == sorted(positions), "PDF scenarios are not in workbook order"

sample = PdfReader(ROOT / "sample-results.pdf")
sample_text = compact(body(sample))
assert compact(expected["comment"]) in sample_text, "Long/Unicode comment changed or truncated"
assert "NotStarted:104" in sample_text
assert all(label in sample_text for label in ["Pass:1", "Fail:1", "PartiallyPassed:1"])
assert compact(expected["source"]["scenarios"][3]["title"]) not in sample_text
assert 'Personcompletingtests:Reviewtester' in sample_text
assert 'Completedby:Reviewtester' in sample_text
assert 'AssignedTester:Lanre' in sample_text
tester_text = compact(body(PdfReader(ROOT / "tester-results.pdf")))
assert 'Testerselection:Lanre' in tester_text
assert '3of15scenarioscompleted' in tester_text and 'NotStarted:12' in tester_text
assert all(label in tester_text for label in ['Pass:1', 'Fail:1', 'PartiallyPassed:1'])
unassigned_text = compact(body(PdfReader(ROOT / "unassigned-results.pdf")))
assert 'AssignedTester:Unassigned' in unassigned_text
assert 'Completedby:Unassignedcasetester' in unassigned_text
assert '1of1scenarioscompleted' in unassigned_text
for name in ["all-scenarios.pdf", "sample-results.pdf", "tester-results.pdf", "unassigned-results.pdf"]:
    with pdfplumber.open(ROOT / name) as pdf:
        for i, page in enumerate(pdf.pages):
            for char in page.chars:
                assert char["x0"] >= 40 and char["x1"] <= page.width - 40, (name, i + 1, "horizontal clipping")
                assert char["top"] >= 35 and char["bottom"] <= page.height - 20, (name, i + 1, "vertical clipping")
print(f"PASS: 749 source fields and workbook order preserved across {len(all_pdf.pages)} pages; all outcomes, counts, completed-only selection and exact long Unicode comments preserved across {len(sample.pages)} sample pages; no text outside page margins.")
